from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageDetail
from taf.ul.ettf.msg_capture.helpers import DynamicId
from taf.ul.ettf.pdml_parser.parser import Enum
from taf.ul.ettf.ta_matchers.matchers import Any, Contains, ExpectationsBuilder, Omit
from taf.ul.ettf.ta_matchers.helpers import WithDynamicIds
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.typed.custom_types import AnyOf


QUANTITIES = ['RSRP', 'RSRQ']
UTRA_QUANTITIES = ['RSCP']


class MeasObjectToAddMod(ExpectationsBuilder):
    def __init__(self):
        super(MeasObjectToAddMod, self).__init__("MeasObjectToAddMod")

    def with_meas_obj_id(self, meas_obj_id=Any()):
        self.append_element(key="measObjectId", element=meas_obj_id)
        return self

    def with_meas_obj(self, meas_obj=Any()):
        self.append_element(key="measObject", element=meas_obj())
        return self


class MeasObjectUTRA(ExpectationsBuilder):
    def __init__(self):
        super(MeasObjectUTRA, self).__init__("measObjectUTRA")

    def with_carrier_freq(self, freq=Any()):
        self.append_element(key="carrierFreq", element=freq)
        return self


class MeasObjectNR(ExpectationsBuilder):
    def __init__(self):
        super(MeasObjectNR, self).__init__("measObjectNR-r15")

    def with_carrier_freq(self, freq=Any()):
        self.append_element(key="carrierFreq-r15", element=freq)
        return self

    def with_nr_band(self, band=Any()):
        self.append_element(key="bandNR-r15", element=Any({
            'setup': band
        }))
        return self

    def with_rs_configssb(self, scs=Any(), ssb_dur=Any(), ssb_periodicity=Any(), ssb_offset=Any()):
        self.append_element(key="rs-ConfigSSB-r15", element=rs_configssb(scs=scs,
                                                                         ssb_dur=ssb_dur,
                                                                         ssb_periodicity=ssb_periodicity,
                                                                         ssb_offset=ssb_offset))
        return self

    def with_offsetfreq(self, offsetfreq=Omit()):
        self.append_element(key="offsetFreq-r15", element=offsetfreq)
        return self

    def with_quantityconfigset(self):
        self.append_element(key="quantityConfigSet-r15", element=Any())
        return self


def rs_configssb(scs=Any(), ssb_dur=Any(), ssb_periodicity=Any(), ssb_offset=Any()):
    return Any({
        'subcarrierSpacingSSB-r15': Any() if isinstance(scs, Any) else Enum(scs, e_scs[scs]),
        'measTimingConfig-r15': Any({
            'ssb-Duration-r15': Any() if isinstance(ssb_dur, Any) else Enum(ssb_dur, e_ssb_duration[ssb_dur]),
            'periodicityAndOffset-r15': Any() if isinstance(ssb_periodicity, Any) else Any({ssb_periodicity: ssb_offset})
        })
    })


e_scs = {
    'kHz15': 0,
    'kHz30': 1,
    'kHz120': 2,
    'kHz240': 3
}


e_ssb_duration = {
    'sf1': 0,
    'sf2': 1,
    'sf3': 2,
    'sf4': 3,
    'sf5': 4
}

e_offset_freq_r15 = {
    'missing': Omit(),
    'any': Any()
}


