class EventB1Nr(ExpectationsBuilder):
    def __init__(self):
        super(EventB1Nr, self).__init__("eventB1-NR-r15")

    def with_threshold_nr(self, threshold_nr=Any()):
        self.append_element(key="b1-ThresholdNR-r15", element=threshold_nr)
        return self

    def with_report_on_leave_r15(self, reportonleave=Any()):
        self.append_element(key="reportOnLeave-r15", element=reportonleave)
        return self

    @staticmethod
    def threshold_nr(quantity):
        return Any({
            'nr-{}-r15'.format(quantity): Any()
        })


class EventB2Nr(ExpectationsBuilder):
    def __init__(self):
        super(EventB2Nr, self).__init__("eventB2-NR-r15")

    def with_threshold_1(self, threshold_nr=Any()):
        self.append_element(key="b2-Threshold1-r15", element=threshold_nr)
        return self

    def with_threshold_2(self, threshold_nr=Any()):
        self.append_element(key="b2-Threshold2NR-r15", element=threshold_nr)
        return self

    @staticmethod
    def threshold_1(quantity):
        return Any({
            'threshold-{}'.format(quantity): Any()
        })

    @staticmethod
    def threshold_2(quantity):
        return Any({
            'nr-{}-r15'.format(quantity): Any()
        })


class EventB1Utra(ExpectationsBuilder):
    def __init__(self):
        super(EventB1Utra, self).__init__("eventB1")

    def with_threshold(self, threshold):
        self.append_element(key="b1-Threshold", element=threshold)
        return self

    @staticmethod
    def threshold(quantity):
        return Any({
            'b1-ThresholdUTRA': Any({
                'utra-{}'.format(quantity): Any()
            })
        })


